def-hyp(
    list-partial(
        Type.annotation(@x, T@Set.ctxt.T),
        Set.mem(x, S@Topology.ctxt.S),
        Type.annotation(@U, Set(T@Set.ctxt.T)),
        Set.subset(U, S@Topology.ctxt.S)
    ),
    Topology.deletedNeighborhood(U, x),
    Logic.and(
        Topology.neighborhood(
            Set.union(U, Set.sep-typed(@y, T@Set.ctxt.T, Eq(y, x))),
            x
        ),
        Set.nmem(x, U)
    )
)
